le kilogram quantity.") ; sh:minCount Literal("1", datatype=xsd:integer) ; sh:node [ sh:class qudt:QuantityValue ; sh:property [ sh:datatype xsd:decimal ; sh:maxCount Literal("1", datatype=xsd:integer) ; sh:minCount Literal("1", datatype=xsd:integer) ; sh:path qudt:numericValue ], [ sh:hasValue unit:KiloGM ; sh:maxCount Literal("1", datatype=xsd:integer) ; sh:minCount Literal("1", datatype=xsd:integer) ; sh:path qudt:unit ] ] ; sh:path nltl:loadedSurvivalCraftRequirement ] ; sh:sparql [ sh:message Literal("Survival-craft capacity must be at least the persons capacity requirement plus the additional equipment capacity requirement, and launching-appliance capacity must be at least the loaded survival-craft requirement.") ; sh:select Literal("
                    PREFIX nltl: <https://w3id.org/nltl/vocab#>
                    PREFIX qudt: <http://qudt.org/schema/qudt/>
                    PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

                    SELECT $this
                    WHERE {
                        $this nltl:personsCapacityRequirement ?persons ;
                              nltl:additionalEquipmentCapacityRequirement ?additional ;
                              nltl:survivalCraftAvailableCapacity ?available ;
                              nltl:loadedSurvivalCraftRequirement ?loaded ;
                              nltl:launchingApplianceCapacity ?launching .
                        ?loaded qudt:numericValue ?loadedValue .
                        ?launching qudt:numericValue ?launchingValue .
                        FILTER (
                            ?available < (?persons + ?additional) ||
                            ?launchingValue < ?loadedValue
                        )
                    }
                ") ] ] , [ sh:property [ sh:datatype xsd:boolean ; sh:hasValue Literal("false" = False, datatype=xsd:boolean) ; sh:maxCount Literal("1", datatype=xsd:integer) ; sh:message Literal("Applicability must indicate that additional equipment is not carried in the survival craft.") ; sh:minCount Literal("1", datatype=xsd:integer) ; sh:path nltl:additionalEquipmentCarriedInSurvivalCraft ] ]"]

